const config = readConfig();
const proxyRes = await probe("proxy");
const backendRes = await probe("backend");
const upstreamRes = await probe("configuredUpstream");
const output = {
  config: config,
  proxy: proxyRes,
  backend: backendRes,
  configuredUpstream: upstreamRes,
  portMatch: config.upstreamPort === config.backendPort,
  finding: config.upstreamPort === config.backendPort ? "Upstream port matches backend port." : "Upstream port mismatch: configured upstream port does not match backend port."
};
console.log(JSON.stringify(output));
